import{_ as o,l as m,o as t,c as n,v as i,p as l,x as e,d as p,i as E,S as u}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Markowitz","description":"","frontmatter":{"title":"Markowitz","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/markowitz.md","filePath":"quant/markowitz.md","lastUpdated":1789023840000}'),s={name:"quant/markowitz.md"};function d(h,a,c,A,w,_){const r=m("Mermaid");return t(),n("div",null,[a[1]||(a[1]=i('<h1 id="markowitz" tabindex="-1">Markowitz <a class="header-anchor" href="#markowitz" aria-label="Permalink to &quot;Markowitz&quot;">​</a></h1><div class="epigraph"><p>组合的风险不是权重的加权平均，而是协方差的二次型；投资者应在均值–方差平面上选择有效前沿，而不是逐只比较「好股票」。</p><footer>—— Markowitz, Portfolio Selection, Journal of Finance, 1952</footer></div><p><a href="/quant/corporate-bond-otc">上一课</a>停在单券流动性。缺口是截面：如何把多资产的均值与协方差写成组合权重。Markowitz（1952）把分散化从谚语写成二次规划：给定期望向量 \\(\\mu\\) 与协方差 \\(\\Sigma\\)，最小化 \\(w^\\top\\Sigma w\\) 并约束期望收益与预算。有效前沿是均值–方差平面上的上半支，两基金定理说任意有效组合都是两个有效基金的混合。Sharpe 与 Lintner 的 <a href="/quant/capm">CAPM</a> 把其中一个基金在均衡里等同于市场。本篇只写选择问题本身：前沿怎么来、卖空与约束如何改变形状、以及为什么同一套公式在估计 \\(\\mu,\\Sigma\\) 之后会变成下一篇要处理的 <a href="/quant/cov-shrinkage">误差放大</a>。1959 年的书把效用与长期投资补全，数学对象没有离开二次风险。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若风险用方差度量，且收益的相关不是零，那么「每只股票单独很好」不能推出「组合很好」。方差是</p> \\[\\sigma_p^2=w^\\top\\Sigma w=\\sum_i\\sum_j w_i w_j\\Sigma_{ij}, \\]<p>对角项是自己的方差，交叉项可以是负的。问题是：在 \\(\\mu,w\\) 的线性约束下，哪一个 \\(w\\) 让 \\(\\sigma_p\\) 最小，以及随着目标期望 \\(\\mu_p\\) 移动，最小风险如何画出一条曲线。Markowitz 假定 \\(\\mu,\\Sigma\\) 已知，讨论的是选择，不是估计。后来的全部病态——权重炸到极端、样本前沿不可信——来自把未知参数当成已知，不是 1952 年公式的内部矛盾。</p><p>效用基础是：二次效用，或椭圆分布下均值方差足够描述偏好。非椭圆的尾部、不可卖空、离散份额、税与杠杆约束，都会让真正的最优离开均方前沿。这些是边界，先把无约束二次问题写清楚，才知道后来每加一条约束，前沿损失了什么。</p><h3 id="方差作为风险的代价" tabindex="-1">方差作为风险的代价 <a class="header-anchor" href="#方差作为风险的代价" aria-label="Permalink to &quot;方差作为风险的代价&quot;">​</a></h3><p>方差对盈亏对称。投资人通常讨厌亏损多于喜欢超额，半方差、VaR、CVaR 会改变目标。Markowitz 自己讨论过半方差，但均方因二次规划可解、与 CAPM 衔接而成为标准。用方差并不意味着相信收益正态：只要偏好或分布让均方成为充分统计，前沿就有规范意义。工程上的问题更常是 \\(\\Sigma\\) 的估计，而不是对称性本身；对称性在期权叠加、违约与趋势跟踪里才会真正破掉。</p><p><span class="marginnote">有效前沿上的点是「给定均值最小方差」，不是「给定方差最大夏普」。无风险资产存在时，切点组合才最大化夏普；没有无风险资产时，前沿上每一点对应不同风险厌恶。把整条前沿上的组合都叫做「最大夏普」是错的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准问题（允许卖空、全投资）为</p> \\[\\min_w \\tfrac12 w^\\top\\Sigma w \\quad\\text{s.t.}\\quad w^\\top\\mu=\\mu_p,\\quad w^\\top\\mathbf{1}=1. \\]<p>\\(\\Sigma\\) 正定时解唯一，用两个拉格朗日乘数得到 \\(w\\) 对 \\(\\mu_p\\) 仿射，于是前沿在 \\((\\sigma,\\mu)\\) 平面上是双曲线。再引入无风险利率 \\(r_f\\)，约束改为权重之和可以小于 1（其余现金），则有效集变成从 \\(r_f\\) 出发与双曲线相切的射线，切点 \\(w_T\\propto \\Sigma^{-1}(\\mu-r_f\\mathbf{1})\\)。两基金：任意有效组合是 \\(w_T\\) 与现金（或两个风险有效基金）的混合。这是 <a href="/quant/capm">CAPM</a> 里「大家都持有同一风险组合」的选择论前半句。</p><p>不允许卖空时，问题变成二次规划，Kuhn–Tucker 条件给出哪些资产权重被顶在零。前沿仍然存在，但不再有简单的全市场两基金：不同 \\(\\mu_p\\) 对应不同的活跃集合。加入行业、杠杆、换手约束后同理。计算上这是标准 QP，难的是输入。最小方差组合（不管均值）是 \\(\\mu_p\\) 约束去掉后的 \\(w\\propto\\Sigma^{-1}\\mathbf{1}\\)，对 \\(\\mu\\) 的估计误差免疫，对 \\(\\Sigma\\) 的误差仍然敏感，这是它在实务上比切点更常见的原因。</p><h3 id="从特征组合到正交分解" tabindex="-1">从特征组合到正交分解 <a class="header-anchor" href="#从特征组合到正交分解" aria-label="Permalink to &quot;从特征组合到正交分解&quot;">​</a></h3><p>\\(\\Sigma^{-1}\\mu\\) 是最大夏普方向（超额），\\(\\Sigma^{-1}\\mathbf{1}\\) 是最小方差方向。任何目标都可以写成若干「特征组合」的线性组合。风险模型把 \\(\\Sigma\\) 写成因子结构 \\(B F B^\\top+\\Delta\\) 之后，优化在因子空间里做，个股特异方差限制集中度——见 <a href="/quant/fundamental-risk-model">基本面风险模型</a>。Markowitz 的数学不依赖因子：因子只是给 \\(\\Sigma\\) 降维，以免样本协方差不可逆。没有因子时，\\(N\\gt T\\) 则 \\(S\\) 奇异，二次规划在未正则化前没有定义。这已经进入估计，不是选择理论。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分散化的机制是协方差：在 \\(\\rho\\lt 1\\) 时，组合方差严格小于权重加权的方差平均。完全相关时前沿退化成线段，分散化消失。负相关资产是前沿向外推的来源。均值的作用是倾斜：高 \\(\\mu\\) 的资产在高风险厌恶时仍可能权重不大，因为切点公式是 \\(\\Sigma^{-1}\\) 乘超额，不是按 \\(\\mu\\) 排序。这解释了为何「看好的股票」在均方最优里可能被做空——它与别的高 \\(\\mu\\) 资产相关太高，边际贡献不足。</p><p>均衡机制不在本篇：把切点等同于市值权重需要同质预期与无摩擦。Markowitz 只给出个人的规范性选择。若每人的 \\(\\mu\\) 不同，每人有自己的切点，市场是它们的加总，不必落在任何一个人的前沿上。Black–Litterman 后来用均衡把 \\(\\mu\\) 的先验拉回市场，那是对估计问题的贝叶斯补丁，见 <a href="/quant/black-litterman">Black-Litterman</a>。</p><p><span class="marginnote">样本里算出的「最优权重」对 \\(\\mu\\) 的微小扰动极度敏感，因为 \\(\\Sigma\\) 的小特征值把噪声放大。这不是要改 1952 年的目标函数，而是要承认输入不是真参数。Michaud 称之为误差最大化：优化器偏爱估得最不准的方向。</span></p><h3 id="与效用最大化的关系" tabindex="-1">与效用最大化的关系 <a class="header-anchor" href="#与效用最大化的关系" aria-label="Permalink to &quot;与效用最大化的关系&quot;">​</a></h3><p>二次效用 \\(E[w^\\top r]-\\frac{\\delta}{2}w^\\top\\Sigma w\\) 的无约束解 \\(w\\propto \\Sigma^{-1}\\mu/\\delta\\)，与切点只差杠杆。CRRA 在对数正态近似下也会落到类似的均方问题。时间可加、再平衡与对冲需求（Merton）会引入状态变量，长期投资者的有效前沿不再是单期 Markowitz。单期公式适用于再平衡频率上可以把未来当「均值方差一层」的账本，不适用于带不可交易收入与随机利率的生命周期问题。写投资政策时应声明是哪一层。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在 \\(N\\) 只股票、两年日度数据上直接求 \\(\\Sigma^{-1}\\mu\\) 当组合。不要把有效前沿的样本内回测当成可实现的夏普：同一数据既估参数又画前沿，偏差已知向上。不要用等权或市值权重的历史表现否定 Markowitz：那是在比较一个稳定的启发式和一个未收缩的估计器，不是在否定均方目标。约束可以当成正则：禁止卖空、限制换手，往往比精致的效用微修更能救命。</p><p>方差不是尾部。杠杆约束、破产、期权卖方的缺口风险，要用别的风险度量或压力。但改用 CVaR 并不自动解决估计：尾部参数更吵。先把 \\(\\Sigma\\) 收缩、因子化，再决定是否离开二次，是更常见的稳健顺序。Markowitz 提供的是问题的正确几何——风险在协方差里，不在单资产排序里——以及一个在输入可靠时仍然正确的解。</p><p><span class="marginnote">1952 年论文用的是「预期收益」的主观估计，不是历史均值必须等于 \\(\\mu\\)。用过去五年的样本均值当 \\(\\mu\\)，是后人图省事，也是切点组合崩溃的主因。Markowitz 对 \\(\\mu\\) 的来源保持开放；对 \\(\\Sigma\\) 用样本协方差则是后来的默认，同样需要收缩。</span></p>',28)),(t(),l(u,null,{default:e(()=>[E(r,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20MU%5B%22%E6%9C%9F%E6%9C%9B%20%CE%BC%22%5D%20--%3E%20QP%5B%22%E4%BA%8C%E6%AC%A1%E8%A7%84%E5%88%92%20min%20w'%CE%A3w%22%5D%0A%20%20SIG%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%20%CE%A3%22%5D%20--%3E%20QP%0A%20%20QP%20--%3E%20EF%5B%22%E5%9D%87%E5%80%BC-%E6%96%B9%E5%B7%AE%E6%9C%89%E6%95%88%E5%89%8D%E6%B2%BF%22%5D%0A%20%20RF%5B%22%E6%97%A0%E9%A3%8E%E9%99%A9%E5%88%A9%E7%8E%87%22%5D%20--%3E%20T%5B%22%E5%88%87%E7%82%B9%20%2F%20%E6%9C%80%E5%A4%A7%E5%A4%8F%E6%99%AE%22%5D%0A%20%20EF%20--%3E%20T%0A%20%20T%20--%3E%20CAPM%5B%22%E5%9D%87%E8%A1%A1%3A%20%E5%88%87%E7%82%B9%20%3D%20%E5%B8%82%E5%9C%BA%20%E2%86%92%20CAPM%22%5D%0A%20%20SIG%20--%3E%20EST%5B%22%CE%A3%2C%20%CE%BC%20%E6%9C%AA%E7%9F%A5%20%E2%86%92%20%E4%BC%B0%E8%AE%A1%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20EST%20--%3E%20SH%5B%22%E6%94%B6%E7%BC%A9%20%2F%20BL%20%2F%20%E9%A3%8E%E9%99%A9%E5%B9%B3%E4%BB%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Markowitz（1952）用组合方差 \\(w^\\top\\Sigma w\\) 作为风险，在目标均值下求有效前沿；分散化来自协方差而不是资产个数。</li><li>允许卖空且 \\(\\Sigma\\) 正定时，解对目标均值仿射；存在无风险资产时切点最大化夏普，两基金定理成立。</li><li>卖空与制度约束改变活跃集合，前沿仍在，闭式两基金不再免费。</li><li>公式假定 \\(\\mu,\\Sigma\\) 已知；实务失败几乎总是估计，尤其是 \\(\\mu\\)，见收缩与 Black–Litterman。</li><li>方差对称、单期、椭圆偏好是建模边界，不是对「不要分散化」的许可。</li><li>出处：Markowitz, <em>Journal of Finance</em>, 1952；展开见 Markowitz, <em>Portfolio Selection: Efficient Diversification of Investments</em>, 1959。</li></ul>',2))])}const k=o(s,[["render",d]]);export{S as __pageData,k as default};
